# this script generates interface.py using 
# linearized_schema.json and gltf_schema_resolved.json (which are in turn generated by the schema_exporter build target)
# and the Gestaltor Automated module that the helper operations interface should be generated for
# e.g. on Windows, place the module in the module_path like this: "build/bin/Release/GestaltorAutomatedWindows.zip"
# this is script has to be then executed from the Gestaltor root directory

import string
import sys
import re
from functools import reduce
import json

# Pathes are relative to Gestaltor root directory
module_path = "build/bin/Release"
linearized_schema_path = "build/bin/Release/linearized_schema.json"
gltf_schema_path = "build/bin/Release/gltf_schema_resolved.json"


output_path = "automated/python/helper_operations/interface.py"

sys.path.append(module_path)
from GestaltorAutomated import core_operations as core

linearized_schema = {}
class_dict = {}

gltf_schema = None

def to_snake_case(name):
    name = re.sub("(.)([A-Z][a-z]+)", r"\1_\2", name)
    name = re.sub("__([A-Z])", r"_\1", name)
    name = re.sub("([a-z0-9])([A-Z])", r"\1_\2", name)
    return name.lower()


def sanitize_class(name):
    name = name.replace(".", "_")
    name = name.replace(" ", "")
    name = name.replace("@", "")
    name = name.replace("/", "_")
    name = name.replace("\\", "_")
    name = name.replace("+", "_")
    if len(name)>1 and name[0]=="_":
        name = name[1:] 
    return name

def sanitize_member(name):
    name = name.replace(".", "_")
    name = name.replace(" ", "")
    name = name.replace("@", "")
    name = name.replace("/", "_")
    name = name.replace("\\", "_")
    name = name.replace("+", "_")
    return name

def create_class(name, path, parent_class):
    name = sanitize_class(str(name))
    if name in class_dict:
        print(" class already exists -> "+str(name) +" - "+path)
    class_dict[name]={}
    class_dict[name]["members"]={}
    class_dict[name]["path"]=path
    class_dict[name]["parent_class"]=parent_class

def add_member(class_name, class_path, member_name, member_type, member_class_name, member_parameter):
    class_name = sanitize_class(str(class_name))
    member_name = sanitize_member(str(member_name))
    member_class_name = sanitize_class(str(member_class_name))
    class_dict[class_name]["members"][member_name]={}
    class_dict[class_name]["members"][member_name]["type"]=member_type
    class_dict[class_name]["members"][member_name]["class_name"]=member_class_name
    class_dict[class_name]["members"][member_name]["member_parameter"]=member_parameter


def indent(line, level):
    indention = ""
    for i in range(level):
        indention += "    "
    return indention + line + "\n"

def compose_class_functions(operations):
    class_functions = ""
    for op_name, op_schema in operations.items():
        if "dangerous" in op_name:
            continue
        op_params = {}
        has_path = False
        for entry in op_schema:
            if  isinstance(entry, dict) and "properties" in entry:
                for param_name, info in entry["properties"].items():
                    param_name = sanitize_member(param_name)
                    if param_name == "path":
                        has_path = True
                        continue
                    if not info:
                        info = {}
                    op_params[param_name]=info
                    #if "required" in entry and param_name in entry["required"]:
                    #    default_value = None 
                    #else:
                    #    default_value = "None" 
                    default_value = "None" 
                    # Remove default values right now because
                    # combinations of parameters were passed to the core
                    # these combinations could conflict e.g.:
                    # convert_image:
                    # mimeType = png and compression = 'ETC1S'
                    #if "default" in info:
                    #    if isinstance(info["default"], str):
                    #        default_value = "'"+info["default"]+"'"
                    #    else:
                    #        default_value = str(info["default"])
                    op_params[param_name]["default"] = default_value


        op_param_string_list = []
        op_param_string_list.append("self")
        # At first, add all parameters without default value:
        for param, info in op_params.items():
            param_string = sanitize_member(param)
            if info["default"] is None:
                op_param_string_list.append(param_string)

        # Now, add parameters with default values (python requirement)
        for param, info in op_params.items():
            param_string = sanitize_member(param)
            if info["default"] is not None:
                param_string += " = "+ info["default"]
                op_param_string_list.append(param_string)


        op_params_string = ", ".join(op_param_string_list)
        line = "def {op_name}({op_params}):"
        line = line.format(op_name=to_snake_case(sanitize_member(op_name)),op_params=op_params_string)
        class_functions += indent(line, 1)
        if has_path:
            class_functions += indent("path = self.path", 2)
        class_functions += indent("local = locals()", 2)  
        class_functions += indent("local.pop('self', None)", 2)
        class_functions += indent("local = {k: v for k, v in local.items() if v != None}", 2)
        line = "pp.call(self, self.handle, '{op_name}', local)".format(op_name=str(op_name))
        class_functions += indent(line, 2)
        class_functions += indent("", 2)
    return class_functions

def compose_class(class_name):
    class_string = ""
    members = class_dict[class_name]["members"]
    path = class_dict[class_name]["path"]
    parent_class = class_dict[class_name]["parent_class"]
    class_header = ""
    class_header += indent( "class "+ class_name +"("+str(parent_class)+"): " ,0)
    class_header += indent("path_pattern = '{path}'".format(path=path),1)

   
    class_init = ""

    if "PropertyArray" in parent_class:
        class_init += indent("def __init__(self, path, handle, type): ", 1 )
        class_init += indent("self.path = path ", 2 )
        class_init += indent("self.handle = handle ", 2 )
        class_init += indent("self.type = type ", 2 )
    elif class_name == "gltf":
        class_init += indent("def __init__(self, handle): ", 1 )
        class_init += indent("self.path = \"/gltf\" ", 2 )
        class_init += indent("self.handle = handle ", 2 )
    else:
        class_init += indent("def __init__(self, path, handle): ", 1 )
        class_init += indent("self.path = path ", 2 )
        class_init += indent("self.handle = handle ", 2 )
        class_init += indent("pp.ObjectProperty.__init__(self, path, handle) ", 2 )


    if path == "/gltf":
        operations = core.get_global_operations()
    else:
        operations = core.get_operations_by_path(path)

    class_functions = compose_class_functions(operations)
    
    member_init = ""

    for prop_name in members:
        prop_info = members[prop_name]  
        if prop_info["type"] == "Value":
            line = "self.{member_name} = pp.GenericValue(str(self.path)+'/{member_name}', self.handle )"
            line = line.format(member_name=prop_name)
            member_init += indent(line, 2)

        if prop_info["type"] == "Object":
            line = "self.{member_name} = {class_name}(str(self.path)+'/{member_name}', self.handle )"
            line = line.format(member_name=prop_name, class_name =prop_info["class_name"] )
            member_init += indent(line, 2)

        if prop_info["type"] == "PropertyArray":
            # e.g. self.images = gltf_images(str(self.path)+'/images', self.handle, gltf_images__d_)
            line = "self.{member_name} = {class_name}(str(self.path)+'/{member_name}', self.handle, {member_parameter})"
            line = line.format(member_name=prop_name, class_name = prop_info["class_name"] , member_parameter = prop_info["member_parameter"] )
            member_init += indent(line, 2)

        if prop_info["type"] == "Reference":
            line = "self.{member_name} = pp.Reference[{class_name}](str(self.path)+'/{member_name}', self.handle, {class_name})"
            line = line.format(member_name=prop_name, class_name = prop_info["class_name"] )
            member_init += indent(line, 2)

        if prop_info["type"] == "ReferenceArray":
            line = "self.{member_name}:list[pp.Reference[{class_name}]] = "
            line += "pp.ReferenceArray[{class_name}](str(self.path)+'/{member_name}', self.handle, {class_name})"
            line = line.format(member_name=prop_name, class_name = prop_info["class_name"] )
            member_init += indent(line, 2)


    class_string += class_header+"\n" 
    class_string += class_init+"\n" 
    class_string += member_init+"\n"
    class_string += class_functions+"\n"

    return class_string

def write_header(file):
    header_string = ""
    header_string += indent("from GestaltorAutomated import proxy_properties as pp",0)
    header_string += "\n"
    
    file.write(header_string)

def write_class(file, class_name):
    class_string = compose_class(class_name)
    file.write(class_string)

def get_class_name(ux3d_path_prefix):
    global linearized_schema
    path_pattern = ux3d_path_prefix+"/\\d+"
    return sanitize_class("/gltf"+path_pattern)


def resolve_object(name, path, gltf_property):
    #print( "resolve_object: "+str(path))
    if not isinstance(gltf_property, dict): 
        print( "no dict: "+str(name))
        return

    parent_class = ""
    if "type" in gltf_property and gltf_property["type"] == "array" and "items" in gltf_property and gltf_property["items"]["type"] == "object":
        array_type = sanitize_class(path+'/\\d+')
        parent_class="pp.PropertyArray["+array_type+"]"
    else:
        parent_class="pp.ObjectProperty"

    name = sanitize_class(path)
    create_class(name, path, parent_class)

    if "items" in gltf_property:
        member_class_name = sanitize_class(name+'/\\d+')
        resolve_object(member_class_name, path+'/\\d+', gltf_property["items"])

    if not "properties" in gltf_property:
        #print( "no properties: "+str(name))
        return
    if gltf_property["properties"] is None:
        return

    for key, property in gltf_property["properties"].items(): 
        member_name = str(key)
        member_type = "Value"
        member_class_name = ""
        member_parameter = ""

        if "ux3d_pathPrefix" in property:
            member_type = "Reference"
            member_class_name = get_class_name(property["ux3d_pathPrefix"])

        if "type" in property and property["type"] == "object":
            member_type = "Object"
            if "title" in property:
                member_class_name = property["title"]
            if member_class_name =="" or member_class_name=="glTF Property":
                member_class_name = key
            skip_object_resolve = False
            if "properties" in property and property["properties"] is None:
                member_type = "Value"
                skip_object_resolve = True
            if not "properties" in property:
                member_type = "Value"
                skip_object_resolve = True
            member_class_name = sanitize_class(path+'/'+member_name)

            if not skip_object_resolve:
                resolve_object(member_class_name, path+'/'+member_name, property)

        # check for array of objects. E.g. /gltf/nodes
        if "type" in property and property["type"] == "array" and "items" in property and property["items"]["type"] == "object":
            member_type = "PropertyArray"
            if "title" in property["items"]:
                member_class_name = property["items"]["title"]
            if member_class_name =="" or member_class_name=="glTF Property":
                member_class_name = key
            member_class_name = sanitize_class(path+'/'+member_name)
            member_parameter = sanitize_class(path+'/'+member_name+'/\\d+')
            resolve_object(member_class_name, path+'/'+member_name+'', property)
        
        # check for array of property references. E.g. /gltf/scenes/0/nodes
        if (    "type" in property and property["type"] == "array" and 
                "items" in property and 
                "ux3d_pathPrefix" in property["items"] and
                property["items"]["type"] == "integer"):
            member_type = "ReferenceArray"
            member_class_name = get_class_name(property["items"]["ux3d_pathPrefix"])

        add_member(name, path, member_name, member_type, member_class_name, member_parameter)


def write_file():
    file = open(output_path, "w")
    write_header(file)
    # reverse order is necessary for providing class definitions 
    for key in reversed(list(class_dict.keys())):
        write_class(file, key)

    file.close()

def generator():
    global linearized_schema
    with open(gltf_schema_path) as f:
        gltf_schema = json.load(f)

    with open(linearized_schema_path) as f:
        linearized_schema = json.load(f)

    resolve_object("gltf","/gltf", gltf_schema)


    write_file()


generator()
